package com.maxedxpbarhider;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Maxed Skill Progress Bar Hider",
	description = "Hides the XP progress bar for maxed skills",
	tags = {"xp", "experience", "progress", "bar", "99", "maxed", "skill", "ui", "hide"}
)
public class MaxedXpBarHiderPlugin extends Plugin
{
	// IDs from the game's xpdrops_setbar script; no named API constants exist.
	static final int XP_DROPS_SET_BAR = 999;
	private static final int XP_DROPS_SKILL_ENUM = 681;
	private static final int TOTAL_XP = 30;
	private static final int MOST_RECENT_SKILL = 31;
	private static final int MAX_SKILL_LEVEL = 99;
	private static final Skill[] SKILLS = Skill.values();

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;

	public MaxedXpBarHiderPlugin()
	{
	}

	MaxedXpBarHiderPlugin(Client client, ClientThread clientThread)
	{
		this.client = client;
		this.clientThread = clientThread;
	}

	private Widget hiddenProgress;

	@Override
	protected void shutDown()
	{
		clientThread.invoke(this::restoreProgress);
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == XP_DROPS_SET_BAR)
		{
			restoreProgress();
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		updateProgress();
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == XP_DROPS_SET_BAR)
		{
			updateProgress();
		}
	}

	private void updateProgress()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int skillId = resolveSkill(client.getVarbitValue(VarbitID.XPDROPS_PROGRESS_TYPE));
		if (skillId < 0 || skillId >= SKILLS.length
			|| client.getRealSkillLevel(SKILLS[skillId]) < MAX_SKILL_LEVEL)
		{
			return;
		}

		Widget progress = client.getWidget(InterfaceID.XpDrops.PROGRESS_CONTAINER);
		if (progress != null && !progress.isSelfHidden())
		{
			// only restore widgets we hid
			hiddenProgress = progress;
			progress.setHidden(true);
		}
	}

	private int resolveSkill(int progressType)
	{
		if (progressType == MOST_RECENT_SKILL)
		{
			return client.getVarcIntValue(VarClientID.XPDROPS_LASTSKILL);
		}
		if (progressType < 0 || progressType >= TOTAL_XP)
		{
			return -1;
		}

		EnumComposition mapping = client.getEnum(XP_DROPS_SKILL_ENUM);
		if (mapping == null)
		{
			return -1;
		}
		return XpSkillMapping.resolve(progressType, mapping.getKeys(),
			mapping.getIntVals(), mapping.getLongVals());
	}

	private void restoreProgress()
	{
		if (hiddenProgress != null)
		{
			hiddenProgress.setHidden(false);
			hiddenProgress = null;
		}
	}
}

package com.maxedxpbarhider;

import net.runelite.api.Skill;

final class XpSkillMapping
{
	private static final int SKILL_COUNT = Skill.values().length;

	private XpSkillMapping()
	{
	}

	static int resolve(int selection, int[] keys, int[] intValues, long[] longValues)
	{
		if (keys == null)
		{
			return -1;
		}
		for (int i = 0; i < keys.length; i++)
		{
			if (keys[i] != selection)
			{
				continue;
			}
			long value;
			if (intValues != null && i < intValues.length)
			{
				value = intValues[i];
			}
			else if (longValues != null && i < longValues.length)
			{
				value = longValues[i];
			}
			else
			{
				return -1;
			}
			return value >= 0 && value < SKILL_COUNT ? (int) value : -1;
		}
		return -1;
	}
}

package com.maxedxpbarhider;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class MaxedXpBarHiderPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MaxedXpBarHiderPlugin.class);
		RuneLite.main(args);
	}
}

package com.maxedxpbarhider;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class PluginBehaviorTest
{
	private Client client;
	private Widget progress;
	private MaxedXpBarHiderPlugin plugin;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		progress = mock(Widget.class);
		ClientThread thread = mock(ClientThread.class);
		doAnswer(invocation -> {
			invocation.<Runnable>getArgument(0).run();
			return null;
		}).when(thread).invoke(any(Runnable.class));
		plugin = new MaxedXpBarHiderPlugin(client, thread);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getVarbitValue(VarbitID.XPDROPS_PROGRESS_TYPE)).thenReturn(31);
		when(client.getVarcIntValue(VarClientID.XPDROPS_LASTSKILL)).thenReturn(Skill.STRENGTH.ordinal());
		when(client.getRealSkillLevel(Skill.STRENGTH)).thenReturn(99);
		when(client.getWidget(InterfaceID.XpDrops.PROGRESS_CONTAINER)).thenReturn(progress);
	}

	@Test
	public void supportsRuneLiteNoArgumentConstruction()
	{
		org.junit.Assert.assertNotNull(new MaxedXpBarHiderPlugin());
	}

	@Test
	public void hidesOnlyProgressAndRestoresOnShutdown()
	{
		plugin.onBeforeRender(new BeforeRender());
		verify(progress).setHidden(true);
		verify(client).getWidget(InterfaceID.XpDrops.PROGRESS_CONTAINER);
		plugin.shutDown();
		verify(progress).setHidden(false);
	}

	@Test
	public void ignoresUnrelatedScripts()
	{
		plugin.onBeforeRender(new BeforeRender());
		clearInvocations(client, progress);
		plugin.onScriptPreFired(new ScriptPreFired(1));
		plugin.onScriptPostFired(new ScriptPostFired(1));
		verifyNoInteractions(client, progress);
	}

	@Test
	public void restoresBeforeXpUpdateAndLeavesLowerSkillVisible()
	{
		plugin.onBeforeRender(new BeforeRender());
		plugin.onScriptPreFired(new ScriptPreFired(MaxedXpBarHiderPlugin.XP_DROPS_SET_BAR));
		verify(progress).setHidden(false);
		clearInvocations(progress);
		when(client.getRealSkillLevel(Skill.STRENGTH)).thenReturn(98);
		plugin.onScriptPostFired(new ScriptPostFired(MaxedXpBarHiderPlugin.XP_DROPS_SET_BAR));
		verifyNoInteractions(progress);
	}

	@Test
	public void reappliesAfterXpScript()
	{
		plugin.onScriptPostFired(new ScriptPostFired(MaxedXpBarHiderPlugin.XP_DROPS_SET_BAR));
		verify(progress).setHidden(true);
	}

	@Test
	public void preservesHiddenGameWidget()
	{
		when(progress.isSelfHidden()).thenReturn(true);
		plugin.onBeforeRender(new BeforeRender());
		plugin.shutDown();
		verify(progress, never()).setHidden(anyBoolean());
	}

	@Test
	public void ignoresTotalDisabledAndInvalidSelections()
	{
		for (int selection : new int[]{30, 32, -1})
		{
			when(client.getVarbitValue(VarbitID.XPDROPS_PROGRESS_TYPE)).thenReturn(selection);
			plugin.onBeforeRender(new BeforeRender());
		}
		verifyNoInteractions(progress);
	}

	@Test
	public void toleratesMissingWidgetAndLoggedOutState()
	{
		when(client.getWidget(InterfaceID.XpDrops.PROGRESS_CONTAINER)).thenReturn(null);
		plugin.onBeforeRender(new BeforeRender());
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		plugin.onBeforeRender(new BeforeRender());
		verifyNoInteractions(progress);
	}
}

package com.maxedxpbarhider;

import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class XpSkillMappingTest
{
	@Test
	public void resolvesStrengthFromEitherNumericStorageType()
	{
		int strength = Skill.STRENGTH.ordinal();
		assertEquals(strength, XpSkillMapping.resolve(7, new int[]{7}, new int[]{strength}, null));
		assertEquals(strength, XpSkillMapping.resolve(7, new int[]{7}, null, new long[]{strength}));
	}

	@Test
	public void rejectsMissingOrInvalidMappingsWithoutThrowing()
	{
		assertEquals(-1, XpSkillMapping.resolve(7, null, null, null));
		assertEquals(-1, XpSkillMapping.resolve(7, new int[]{7}, null, null));
		assertEquals(-1, XpSkillMapping.resolve(7, new int[]{7}, new int[0], null));
		assertEquals(-1, XpSkillMapping.resolve(7, new int[]{8}, new int[]{2}, null));
		assertEquals(-1, XpSkillMapping.resolve(7, new int[]{7}, new int[]{-1}, null));
		assertEquals(-1, XpSkillMapping.resolve(7, new int[]{7}, null, new long[]{Long.MAX_VALUE}));
		assertEquals(-1, XpSkillMapping.resolve(7, new int[]{7}, new int[]{Skill.values().length}, null));
	}
}
